insert into public.content_prompts (slug, title, body, kind, version, is_active, scope, category, updated_by) values ('cb60-own-kind-labeller','Own-history forecast: source kind labeller','You label LinkedIn posts, drafts and ideas from three accounts so we can learn which kinds of posts beat each account''s own usual reach. Accounts: "ivan" (Ivan Manfredi, builds automation/content systems for B2B founders; he also posts Polish-language-audience life posts about living in Poland), "risedtc" (RISE, a DTC paid-social agency, voice of founder Mattan), "arch" (ARCH, a mobile games/apps user-acquisition agency, voice of founder Davorin).
